const brief=document.querySelector('#brief');
const demo=document.querySelector('#demo');
const form=document.querySelector('#brief-form');
let preparedBrief='';let activeSolution='';
for(const button of document.querySelectorAll('[data-brief]'))button.addEventListener('click',()=>brief.showModal());
for(const button of document.querySelectorAll('dialog .close'))button.addEventListener('click',()=>button.closest('dialog').close());
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',event=>{const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()});
const menu=document.querySelector('#menu');const nav=document.querySelector('nav');
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');nav.classList.toggle('open',open)});
for(const link of nav.querySelectorAll('a'))link.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation')});
for(const button of document.querySelectorAll('[data-filter]'))button.addEventListener('click',()=>{for(const item of document.querySelectorAll('[data-filter]')){item.classList.toggle('active',item===button);item.setAttribute('aria-pressed',String(item===button))}for(const card of document.querySelectorAll('[data-category]'))card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter});
const demos={customers:{title:'A clearer customer journey.',description:'An example of how a customer workspace could organize your pipeline and keep every conversation connected.',service:'Customer management solution',html:'<h3>Example customer pipeline</h3><div class="demo-row"><b>Website enquiry</b><span>New lead · Assign an owner</span></div><div class="demo-row"><b>Discovery conversation</b><span>Qualified · Capture requirements</span></div><div class="demo-row"><b>Project proposal</b><span>Follow-up · Agree next steps</span></div><div class="demo-row"><b>Customer handover</b><span>Active · Grow the relationship</span></div>'},operations:{title:'Make the next step obvious.',description:'Try this example checklist. A workflow solution can help bring tasks, ownership, and project progress into one place.',service:'Operations & workflow solution',html:'<h3>Example project checklist</h3><label class="demo-check"><input type="checkbox" checked>Define the project goals</label><label class="demo-check"><input type="checkbox">Assign owners and milestones</label><label class="demo-check"><input type="checkbox">Review and approve the work</label><label class="demo-check"><input type="checkbox">Prepare the launch handover</label>'},insights:{title:'See what needs your attention.',description:'Bring the measures that matter into focus. We can discuss your data sources, reporting needs, and the decisions you want to support.',service:'Reporting & insights solution',html:'<h3>Example reporting areas</h3><div class="demo-row"><b>Sales pipeline</b><span>Enquiries · Opportunities · Customers</span></div><div class="demo-row"><b>Project delivery</b><span>Workload · Milestones · Progress</span></div><div class="demo-row"><b>Operations</b><span>Throughput · Trends · Exceptions</span></div><div class="demo-row"><b>Your own metrics</b><span>Define what matters to your business</span></div>'}};
for(const button of document.querySelectorAll('[data-demo]'))button.addEventListener('click',()=>{const selected=demos[button.dataset.demo];activeSolution=selected.service;document.querySelector('#demo-title').textContent=selected.title;document.querySelector('#demo-description').textContent=selected.description;document.querySelector('#demo-content').innerHTML=selected.html;demo.showModal()});
document.querySelector('#discuss').addEventListener('click',()=>{demo.close();form.elements.service.value=activeSolution;brief.showModal()});
form.addEventListener('submit',event=>{event.preventDefault();if(!form.reportValidity())return;const data=new FormData(form);preparedBrief=['Ubernyx Gear — Project enquiry','','Name: '+data.get('name'),'Email: '+data.get('email'),'Interested in: '+data.get('service'),'','Project details:',data.get('details')].join('\n');document.querySelector('#fallback').hidden=false;window.location.href='mailto:info@ubernyx.com?subject='+encodeURIComponent('Project enquiry: '+data.get('service'))+'&body='+encodeURIComponent(preparedBrief)});
document.querySelector('#download').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([preparedBrief],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='ubernyx-gear-project-brief.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
document.querySelector('#year').textContent=new Date().getFullYear();
